package legacy

// Synthetic databases use the source table/column/constraint facts. No Python
// runtime or private database is executed or copied by these tests.
const fixtureSchema = `PRAGMA user_version=1;
CREATE TABLE controller_metadata(singleton INTEGER PRIMARY KEY CHECK(singleton=1), data_model_version INTEGER NOT NULL,min_writer_build INTEGER NOT NULL CHECK(min_writer_build>0));
CREATE TABLE review_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),state_json TEXT NOT NULL);
CREATE TABLE job_metadata (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), jobs_schema_version INTEGER NOT NULL, controller_schema_version INTEGER NOT NULL, controller_data_model_version INTEGER NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, worker TEXT NOT NULL, workstream_id TEXT, title TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('active', 'parked', 'blocked', 'completed')), is_primary INTEGER NOT NULL CHECK (is_primary IN (0, 1)), revision INTEGER NOT NULL CHECK (revision > 0), brief_revision INTEGER NOT NULL CHECK (brief_revision > 0), summary TEXT NOT NULL, progress TEXT NOT NULL, blocker TEXT NOT NULL, checklist_json TEXT NOT NULL, chat_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK (is_primary = 0 OR status NOT IN ('parked', 'completed')));
CREATE TABLE job_revisions (job_id TEXT NOT NULL REFERENCES jobs(id), revision INTEGER NOT NULL CHECK (revision > 0), brief_revision INTEGER NOT NULL CHECK (brief_revision > 0), created_at TEXT NOT NULL, state_json TEXT NOT NULL, PRIMARY KEY (job_id, revision));
CREATE TABLE job_briefs (job_id TEXT NOT NULL REFERENCES jobs(id), brief_revision INTEGER NOT NULL CHECK (brief_revision > 0), created_at TEXT NOT NULL, brief TEXT NOT NULL, PRIMARY KEY (job_id, brief_revision));
CREATE TABLE job_updates (sequence INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES jobs(id), created_at TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE job_checkpoints (sequence INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES jobs(id), created_at TEXT NOT NULL, done TEXT NOT NULL, next_steps TEXT NOT NULL, blocker TEXT NOT NULL, pointers_json TEXT NOT NULL);
CREATE TABLE job_notes (id TEXT PRIMARY KEY, body TEXT NOT NULL, worker TEXT, job TEXT, phase TEXT, kind TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'consumed', 'dismissed')), dismissal_reason TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK (worker IS NOT NULL OR job IS NOT NULL OR phase IS NOT NULL), CHECK ((status = 'dismissed' AND length(dismissal_reason) > 0) OR (status <> 'dismissed' AND dismissal_reason = '')));
CREATE TABLE job_note_revisions (note_id TEXT NOT NULL REFERENCES job_notes(id), revision INTEGER NOT NULL CHECK (revision > 0), created_at TEXT NOT NULL, state_json TEXT NOT NULL, PRIMARY KEY (note_id, revision));
CREATE TABLE job_worker_state (worker TEXT PRIMARY KEY, paused INTEGER NOT NULL CHECK (paused IN (0, 1)), reason TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK (paused = 1 OR reason = ''));
CREATE TABLE job_worker_state_history (sequence INTEGER PRIMARY KEY AUTOINCREMENT, worker TEXT NOT NULL, created_at TEXT NOT NULL, paused INTEGER NOT NULL CHECK (paused IN (0, 1)), reason TEXT NOT NULL, CHECK (paused = 1 OR reason = ''));
CREATE TABLE job_imports (manifest_fingerprint TEXT PRIMARY KEY, created_at TEXT NOT NULL, manifest_json TEXT NOT NULL, source_contents_json TEXT NOT NULL, provenance_json TEXT NOT NULL);
CREATE TABLE inbox_metadata (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), inbox_schema_version INTEGER NOT NULL);
CREATE TABLE inbox_messages (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, body TEXT NOT NULL, author TEXT, job TEXT, pr INTEGER, reply_to TEXT REFERENCES inbox_messages(id), created_at TEXT NOT NULL, seen_at TEXT, acknowledged_at TEXT, CHECK (pr IS NULL OR pr > 0), CHECK (reply_to IS NULL OR reply_to <> id), CHECK (acknowledged_at IS NULL OR seen_at IS NOT NULL));
CREATE TABLE map_metadata (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), map_schema_version INTEGER NOT NULL, controller_schema_version INTEGER NOT NULL, controller_data_model_version INTEGER NOT NULL);
CREATE TABLE map_workstreams (id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK (revision > 0), state TEXT NOT NULL, now_text TEXT NOT NULL, milestone TEXT NOT NULL, phase_states_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE map_return_points (id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK (revision > 0), state TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE map_revisions (record_type TEXT NOT NULL CHECK (record_type IN ('workstream', 'return_point')), record_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision > 0), created_at TEXT NOT NULL, snapshot_json TEXT NOT NULL, PRIMARY KEY (record_type, record_id, revision));
CREATE TABLE map_imports (source_fingerprint TEXT PRIMARY KEY, created_at TEXT NOT NULL, status_source TEXT NOT NULL, status_sha256 TEXT NOT NULL, progress_source TEXT NOT NULL, progress_sha256 TEXT NOT NULL, original_values_json TEXT NOT NULL, manifest_json TEXT NOT NULL, provenance_json TEXT NOT NULL);
CREATE TABLE review_records_metadata (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), records_schema_version INTEGER NOT NULL, controller_schema_version INTEGER NOT NULL, controller_data_model_version INTEGER NOT NULL, min_writer_build INTEGER NOT NULL CHECK (min_writer_build > 0));
CREATE TABLE review_runs (run_id TEXT PRIMARY KEY, source_pr INTEGER NOT NULL CHECK (source_pr > 0), channel TEXT NOT NULL CHECK (channel IN ('hosted', 'cli', 'manual', 'subagent')), source_head TEXT, reviewer TEXT NOT NULL, scope TEXT NOT NULL CHECK (scope IN ('broad', 'narrow')), coverage_limits_json TEXT NOT NULL, import_payload_json TEXT NOT NULL, outcome TEXT NOT NULL CHECK (outcome IN ('completed', 'incomplete', 'failed')), attributable INTEGER NOT NULL CHECK (attributable IN (0, 1)), started_at TEXT NOT NULL, finished_at TEXT, found_count INTEGER NOT NULL CHECK (found_count >= 0), accepted_count INTEGER NOT NULL CHECK (accepted_count >= 0), routed_count INTEGER NOT NULL CHECK (routed_count >= 0), finalized INTEGER NOT NULL CHECK (finalized IN (0, 1)), finalized_at TEXT, CHECK (accepted_count + routed_count <= found_count), CHECK ((finalized = 0 AND finalized_at IS NULL) OR (finalized = 1 AND finalized_at IS NOT NULL)), UNIQUE (run_id, source_pr, channel));
CREATE TABLE findings (finding_id TEXT PRIMARY KEY, source_pr INTEGER NOT NULL CHECK (source_pr > 0), source_channel TEXT NOT NULL CHECK (source_channel IN ('hosted', 'cli', 'manual', 'subagent')), source_finding_key TEXT NOT NULL, first_seen_at TEXT NOT NULL, UNIQUE (source_pr, source_channel, source_finding_key), UNIQUE (finding_id, source_pr, source_channel));
CREATE TABLE finding_observations (run_id TEXT NOT NULL, finding_id TEXT NOT NULL, source_pr INTEGER NOT NULL, source_channel TEXT NOT NULL, title TEXT NOT NULL, detail TEXT NOT NULL, disposition TEXT NOT NULL CHECK (disposition IN ('accepted', 'routed', 'rejected', 'unresolved')), route_id TEXT, display_severity TEXT CHECK (display_severity IS NULL OR display_severity IN ('Critical', 'Major', 'Minor', 'Trivial')), PRIMARY KEY (run_id, finding_id), FOREIGN KEY (run_id, source_pr, source_channel) REFERENCES review_runs(run_id, source_pr, channel), FOREIGN KEY (finding_id, source_pr, source_channel) REFERENCES findings(finding_id, source_pr, source_channel), FOREIGN KEY (route_id, finding_id) REFERENCES routes(route_id, finding_id));
CREATE TABLE routes (route_id TEXT PRIMARY KEY, finding_id TEXT NOT NULL UNIQUE, source_pr INTEGER NOT NULL, source_channel TEXT NOT NULL, target_pr INTEGER CHECK (target_pr IS NULL OR target_pr > 0), status TEXT NOT NULL CHECK (status IN ('open', 'accepted_fixed', 'rejected')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (route_id, finding_id), FOREIGN KEY (finding_id, source_pr, source_channel) REFERENCES findings(finding_id, source_pr, source_channel));
CREATE TABLE route_target_history (sequence INTEGER PRIMARY KEY AUTOINCREMENT, route_id TEXT NOT NULL, target_pr INTEGER CHECK (target_pr IS NULL OR target_pr > 0), changed_at TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, FOREIGN KEY (route_id) REFERENCES routes(route_id));
CREATE TABLE decisions (decision_id TEXT PRIMARY KEY, decision_scope TEXT NOT NULL CHECK (decision_scope IN ('source', 'target')), run_id TEXT, finding_id TEXT NOT NULL, route_id TEXT, decision_pr INTEGER NOT NULL CHECK (decision_pr > 0), target_pr INTEGER CHECK (target_pr IS NULL OR target_pr > 0), decision TEXT NOT NULL CHECK (decision IN ('accepted', 'routed', 'rejected', 'deferred')), actor TEXT NOT NULL, reason TEXT NOT NULL, decided_at TEXT NOT NULL, CHECK ((decision_scope = 'source' AND run_id IS NOT NULL) OR (decision_scope = 'target' AND run_id IS NULL AND route_id IS NOT NULL)), FOREIGN KEY (run_id, finding_id) REFERENCES finding_observations(run_id, finding_id), FOREIGN KEY (route_id, finding_id) REFERENCES routes(route_id, finding_id));
CREATE TABLE resolutions (resolution_id TEXT PRIMARY KEY, route_id TEXT NOT NULL, resolution_pr INTEGER NOT NULL CHECK (resolution_pr > 0), outcome TEXT NOT NULL CHECK (outcome IN ('accepted_fixed', 'rejected')), actor TEXT NOT NULL, proof_or_reason TEXT NOT NULL, resolved_at TEXT NOT NULL, FOREIGN KEY (route_id) REFERENCES routes(route_id));
CREATE TABLE source_finding_resolutions (resolution_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, finding_id TEXT NOT NULL, source_pr INTEGER NOT NULL CHECK (source_pr > 0), source_channel TEXT NOT NULL CHECK (source_channel IN ('hosted', 'cli', 'manual', 'subagent')), outcome TEXT NOT NULL CHECK (outcome = 'accepted_fixed'), fix_sha TEXT NOT NULL CHECK (length(fix_sha) IN (40, 64)), actor TEXT NOT NULL, proof_note TEXT NOT NULL, resolved_at TEXT NOT NULL, UNIQUE (run_id, finding_id), FOREIGN KEY (run_id, source_pr, source_channel) REFERENCES review_runs(run_id, source_pr, channel), FOREIGN KEY (run_id, finding_id) REFERENCES finding_observations(run_id, finding_id));
CREATE TABLE source_finding_resolution_corrections (sequence INTEGER PRIMARY KEY AUTOINCREMENT, correction_id TEXT NOT NULL UNIQUE, resolution_id TEXT NOT NULL, expected_fix_sha TEXT NOT NULL CHECK (length(expected_fix_sha) IN (40, 64)), corrected_fix_sha TEXT NOT NULL CHECK (length(corrected_fix_sha) IN (40, 64)), actor TEXT NOT NULL, reason TEXT NOT NULL, proof_note TEXT NOT NULL, corrected_at TEXT NOT NULL, FOREIGN KEY (resolution_id) REFERENCES source_finding_resolutions(resolution_id));
CREATE TABLE review_attempts (attempt_id TEXT PRIMARY KEY, source_pr INTEGER NOT NULL CHECK (source_pr > 0), channel TEXT NOT NULL CHECK (channel IN ('hosted', 'cli', 'subagent')), candidate_sha TEXT, state TEXT NOT NULL CHECK (state IN ('started', 'completed', 'failed', 'rate_limited', 'timed_out', 'ambiguous')), started_at TEXT NOT NULL, finished_at TEXT, duration_seconds INTEGER CHECK (duration_seconds IS NULL OR duration_seconds >= 0), exit_status INTEGER, trigger_id TEXT, provider_review_id TEXT, checkpoint_id TEXT, run_id TEXT, diagnostic TEXT NOT NULL DEFAULT '', metadata_json TEXT NOT NULL, CHECK ((state = 'started' AND finished_at IS NULL) OR (state != 'started' AND finished_at IS NOT NULL)), FOREIGN KEY (run_id) REFERENCES review_runs(run_id));
CREATE TABLE review_artifacts (attempt_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('cli_events', 'cli_raw_output', 'cli_diagnostic', 'hosted_review', 'hosted_comments', 'metadata')), content TEXT NOT NULL, source_sha256 TEXT NOT NULL, redactions INTEGER NOT NULL CHECK (redactions >= 0), PRIMARY KEY (attempt_id, kind), FOREIGN KEY (attempt_id) REFERENCES review_attempts(attempt_id));
CREATE TABLE source_decision_corrections (sequence INTEGER PRIMARY KEY AUTOINCREMENT, correction_id TEXT NOT NULL UNIQUE, supersedes_id TEXT NOT NULL, run_id TEXT NOT NULL, finding_id TEXT NOT NULL, decision TEXT NOT NULL CHECK (decision IN ('accepted', 'routed', 'rejected')), target_pr INTEGER CHECK (target_pr IS NULL OR target_pr > 0), actor TEXT NOT NULL, reason TEXT NOT NULL, decided_at TEXT NOT NULL, FOREIGN KEY (run_id, finding_id) REFERENCES finding_observations(run_id, finding_id));
CREATE TABLE provider_origins (repository TEXT NOT NULL, source_pr INTEGER NOT NULL CHECK (source_pr > 0), channel TEXT NOT NULL CHECK (channel IN ('hosted', 'cli')), provider_id TEXT NOT NULL, checkpoint_id INTEGER NOT NULL CHECK (checkpoint_id > 0), checkpoint_fingerprint TEXT NOT NULL, run_id TEXT NOT NULL UNIQUE, PRIMARY KEY (repository, source_pr, checkpoint_id), UNIQUE (repository, source_pr, channel, provider_id), FOREIGN KEY (run_id) REFERENCES review_runs(run_id));
CREATE TABLE imported_artifacts (run_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('cli_events', 'cli_raw_output', 'cli_diagnostic', 'hosted_review', 'hosted_comments', 'metadata')), content TEXT NOT NULL, source_sha256 TEXT NOT NULL, redactions INTEGER NOT NULL CHECK (redactions >= 0), PRIMARY KEY (run_id, kind), FOREIGN KEY (run_id) REFERENCES review_runs(run_id));
CREATE TABLE historical_provider_gaps (repository TEXT NOT NULL, source_pr INTEGER NOT NULL CHECK (source_pr > 0), channel TEXT NOT NULL CHECK (channel IN ('hosted', 'cli')), checkpoint_id INTEGER NOT NULL CHECK (checkpoint_id > 0), checkpoint_fingerprint TEXT NOT NULL, checkpoint_json TEXT NOT NULL, checkpoint_source_sha256 TEXT NOT NULL, checkpoint_redactions INTEGER NOT NULL CHECK (checkpoint_redactions >= 0), missing_reason TEXT NOT NULL, PRIMARY KEY (repository, source_pr, checkpoint_id));
CREATE TABLE historical_gap_artifacts (repository TEXT NOT NULL, source_pr INTEGER NOT NULL, checkpoint_id INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('cli_events', 'cli_raw_output', 'cli_diagnostic', 'hosted_review', 'hosted_comments', 'metadata')), content TEXT NOT NULL, source_sha256 TEXT NOT NULL, redactions INTEGER NOT NULL CHECK (redactions >= 0), PRIMARY KEY (repository, source_pr, checkpoint_id, kind), FOREIGN KEY (repository, source_pr, checkpoint_id) REFERENCES historical_provider_gaps(repository, source_pr, checkpoint_id));`
